@inherits UmbracoViewPage<BlogFrontPage>
@{
	Layout = "_Layout.cshtml";
	ViewData["Title"] = Model.Heading ?? Model.Name();
}
@await Html.GetBlockGridHtmlAsync(Model, "blocks")
<section class="py-12">
	<h2 class="text-2xl font-bold">Latest posts</h2>
	<div class="mt-6 grid gap-6 sm:grid-cols-2">
		@foreach (var post in Model.Children<BlogPost>().Where(p => p.IsVisible()))
		{
			<article class="rounded-xl border border-slate-800 bg-slate-900 p-6">
				<h3 class="text-xl font-semibold">
					<a href="@post.Url()" class="hover:text-emerald-400">@post.Name()</a>
				</h3>
				<p class="mt-2 text-slate-400">@post.Excerpt</p>
				<a href="@post.Url()" class="mt-4 inline-block text-sm font-medium text-emerald-400 hover:underline">Read post &rarr;</a>
			</article>
		}
	</div>
</section>

