	@if (!string.IsNullOrEmpty(Model.ImageUrl))
	{
		<img src="@Model.ImageUrl" alt="" class="absolute inset-0 h-full w-full object-cover opacity-40" />
	}
	<div class="relative bg-gradient-to-t from-slate-950 via-slate-950/70 to-slate-950/30 px-8 py-20 sm:px-12 sm:py-28">
		<h1 class="max-w-2xl text-4xl font-bold tracking-tight sm:text-5xl">@Model.Heading</h1>
		@if (!string.IsNullOrEmpty(Model.Subheading))
		{
			<p class="mt-4 max-w-2xl text-lg text-slate-300">@Model.Subheading</p>
		}
	</div>
</section>

